```js
// node fetchTitle.js <url>
const url = process.argv[2];
if (!url) { console.error('Usage: node fetchTitle.js <url>'); process.exit(1); }
const html = await (await fetch(url)).text();
console.log(html.match(/<title>(.*?)<\/title>/i)?.[1] || 'No title');
```

